eyes=[
 dict(id="jeanne",short="Jeanne des Anges",name="Jeanne des Anges (Jeanne de Belcier)",life="1602–1665",
  role="Prioress of the Ursuline convent of Loudun, aged about 30 in 1632; of a noble family of Saintonge",
  side="Ursulines of Loudun; the possessed",where="Ursuline convent, Loudun; in 1638 on the road to Annecy and Paris",
  lat=47.010,lon=0.083,waypoints=[dict(lat=47.010,lon=0.083,label="Loudun convent 1632–38"),dict(lat=48.877,lon=2.180,label="Rueil, Richelieu, 1638"),dict(lat=48.898,lon=2.094,label="Saint-Germain, the court, 1638"),dict(lat=45.899,lon=6.129,label="Annecy, tomb of Francis de Sales, 1638"),dict(lat=47.010,lon=0.083,label="Loudun, autobiography c. 1642–44")],
  vantage=0,vantage_label="the possessed prioress",form="memoir (written later) and dated letters",language="French",
  authenticity="Her autobiography was written about ten years after the events, c. 1642–44, for her Jesuit director Jean-Baptiste Saint-Jure, and survives in manuscript. It was first printed in 1886 by the physicians Gabriel Legué and Georges Gilles de la Tourette with a preface by J.-M. Charcot, under the title 'Sœur Jeanne des Anges… Autobiographie d'une hystérique possédée'; that title and the medical notes are the 1886 editors' framing, not hers. A 1990 reissue (Jérôme Millon, Grenoble) adds her letters to Saint-Jure and essays by Ferdinand Cavallera and Michel de Certeau.",
  bio="Jeanne des Anges led a small community of about seventeen nuns in a poor, recently founded house. She was the first and most prominent of the sisters said to be possessed, and later the most celebrated: after 1635 names said to be written by departing demons appeared on her left hand, and in 1638 she toured France showing them. Her own account is a late, reflective spiritual autobiography that admits pride and self-deception while upholding the reality of what she suffered.",
  sources=[dict(title="Sœur Jeanne des Anges, supérieure des Ursulines de Loudun: autobiographie d'une hystérique possédée, ed. G. Legué and G. Gilles de la Tourette (Paris, 1886)",url=JDA),dict(title="Autobiographie, 2nd corrected ed. (Grenoble: Jérôme Millon, 1990), BnF record",url="https://catalogue.bnf.fr/ark:/12148/cb36654014x")]),
 dict(id="grandier",short="Grandier",name="Urbain Grandier",life="1590–1634",
  role="Parish priest of Saint-Pierre-du-Marché and canon of Sainte-Croix, Loudun, from 1617; aged 42 in 1632",
  side="the accused; friends among Loudun's notables",where="Loudun; prisoner at Angers, Dec 1633–spring 1634; Loudun for trial",
  lat=47.010,lon=0.083,waypoints=[dict(lat=47.010,lon=0.083,label="Loudun, curé from 1617"),dict(lat=47.478,lon=-0.563,label="Prison at Angers, Dec 1633–1634"),dict(lat=47.010,lon=0.083,label="Loudun, trial and death, Aug 1634")],
  vantage=0,vantage_label="the accused priest",form="treatise (manuscript), trial statements in official records",language="French",
  authenticity="His 'Traicté du célibat des prestres', an unpublished manuscript defending the marriage of priests, was printed in 1866 by Robert Luzarche (Paris: Pincebourde, 'Petite bibliothèque des curieux'). His words at trial and at the stake survive only as reported by hostile and friendly witnesses and in the official records.",
  bio="An eloquent, learned and worldly priest, Grandier had powerful enemies in Loudun long before 1632, after earlier prosecutions over alleged misconduct from which the archbishop of Bordeaux cleared him. The nuns named him as the sorcerer behind their possession although, by most accounts, none had met him. He denied the charges to the end and never confessed.",
  sources=[dict(title="Traicté du célibat des prestres, ed. R. Luzarche (Paris, 1866), Penn Libraries record",url="https://find.library.upenn.edu/catalog/9943765003503681"),dict(title="The History of the Devils of Loudun, tr. E. Goldsmid (1887), Project Gutenberg",url=GUT)]),
 dict(id="sourdis",short="Sourdis",name="Henri d'Escoubleau de Sourdis",life="1594–1645",
  role="Archbishop of Bordeaux, metropolitan over the diocese of Poitiers",side="higher Church authority",where="Bordeaux; his visits and orders to Loudun",
  lat=44.838,lon=-0.579,vantage=3,vantage_label="the archbishop at a distance",form="official record (tribunal sentence and ordinances)",language="French",
  authenticity="Known through the acts of his tribunal and his ordinances, as cited in 1634 narratives and later histories; the originals have not been checked here.",
  bio="Sourdis's court acquitted Grandier in 1631 of the charges on which the bishop of Poitiers had condemned him. When the possession began, he sent his own physician and then ordered the exorcisms stopped and the nuns kept apart, after which the manifestations faded for a time. His intervention is the first official brake in the story; a royal commission later went round it.",
  sources=[dict(title="The History of the Devils of Loudun, tr. E. Goldsmid (1887), Project Gutenberg",url=GUT)]),
 dict(id="desniau",short="des Niau",name="Monsieur des Niau (attributed)",life="fl. 1634",
  role="Counsellor at La Flèche (as identified by his 1887 editor); an eyewitness to the exorcisms and the trial",side="believer in the possession and Grandier's guilt",where="Loudun, 1632–34",
  lat=47.010,lon=0.083,vantage=1,vantage_label="believing eyewitness",form="chronicle (eyewitness narrative, printed 1634)",language="French",
  authenticity="'La véritable histoire des diables de Loudun… par un témoin' was printed at Poitiers by J. Thoreau and the widow Ménier in 1634. Edmund Goldsmid, who owned one of two known copies, attributed it to des Niau and translated it as 'The History of the Devils of Loudun' (Edinburgh, privately printed, 1887). Goldsmid's volumes also carry later material and appendices, so not every passage in them dates from 1634.",
  bio="The anonymous witness writes as a firm believer: he records the nuns' sufferings, the exorcists' tests and the evidence against Grandier, and dates the legal steps carefully. His narrative is the believers' case set down within months of the burning, and its dates line up closely with the official proceedings.",
  sources=[dict(title="The History of the Devils of Loudun, tr. E. Goldsmid (1887), Project Gutenberg",url=GUT)]),
 dict(id="laubardemont",short="Laubardemont",name="Jean Martin de Laubardemont",life="c. 1590–1653",
  role="Councillor of state and royal commissioner, an agent of Cardinal Richelieu",side="the Crown; prosecution",where="Loudun, Sept 1633 and Dec 1633–Aug 1634",
  lat=47.010,lon=0.083,waypoints=[dict(lat=48.857,lon=2.352,label="Paris, commission 30 Nov 1633"),dict(lat=47.010,lon=0.083,label="Loudun, inquiry and trial")],
  vantage=0,vantage_label="the king's commissioner",form="official record (commissions, procès-verbaux, sentence)",language="French",
  authenticity="His commission of 30 November 1633, the Council decree of 31 May 1634 and the sentence of 18 August 1634 survive in print and manuscript and are quoted in 1634 narratives and later histories. Dates here follow those printed narratives.",
  bio="Laubardemont first came to Loudun in 1633 on a different errand, the demolition of the town's fortified keep. He returned with full powers to investigate the possession, had Grandier arrested, gathered testimony, and presided over the special court of judges from neighbouring jurisdictions that condemned him. His records are the state's voice in the affair.",
  sources=[dict(title="Notre Dame research guide on the Loudun possessions (sentence in English)",url=ND),dict(title="The History of the Devils of Loudun, tr. E. Goldsmid (1887)",url=GUT)]),
 dict(id="tranquille",short="Tranquille",name="Father Tranquille of Saint-Rémi, OFM Cap.",life="d. 1638",
  role="Capuchin friar and one of the principal exorcists, 1634",side="exorcists; believers",where="Loudun churches and convent",
  lat=47.010,lon=0.083,vantage=0,vantage_label="exorcist",form="pamphlet (printed account) and procès-verbaux",language="French",
  authenticity="The 'Véritable relation des justes procédures observées au fait de la possession des Ursulines de Loudun et au procès de Grandier' (Paris, 1634), signed with initials, is generally attributed to him; the attribution and exact month of printing are not checked here.",
  bio="Tranquille was among the exorcists who worked the public sessions of 1634 and defended the proceedings in print as just and regular. Accounts friendly to the exorcists report that he himself suffered torments in later years and died in 1638, which they read as the demons' revenge; critics read the same events otherwise.",
  sources=[dict(title="Notre Dame research guide on the Loudun possessions",url=ND)]),
 dict(id="duncan",short="Duncan",name="Marc (Mark) Duncan",life="c. 1570–1640",
  role="Scottish-born Protestant physician and principal of the Protestant academy at Saumur; physician to Marshal de Brézé",side="sceptic; medical observer",where="Saumur, visiting Loudun 1634",
  lat=47.260,lon=-0.077,waypoints=[dict(lat=47.260,lon=-0.077,label="Saumur"),dict(lat=47.010,lon=0.083,label="Loudun, exorcisms 1634")],
  vantage=1,vantage_label="sceptical physician",form="treatise (printed anonymously, 1634)",language="French",
  authenticity="The 'Discours de la possession des religieuses ursulines de Loudun' (1634) appeared without his name; its attribution to Duncan is standard. Not seen in facsimile here.",
  bio="Duncan watched the nuns and argued that what he saw was explained by disordered imagination and melancholy, not by demons, while stopping short of calling it deliberate fraud. His dissent put him at risk; contemporaries report that Laubardemont's displeasure was checked only by Marshal de Brézé's protection.",
  sources=[dict(title="Chalmers's Biographical Dictionary: Duncan, Mark",url="https://words.fromoldbooks.org/Chalmers-Biography/d/duncan-mark.html"),dict(title="C. E. Stephenson, 'Looking Back: The possessions at Loudun', The Psychologist (2014)",url=BPS)]),
 dict(id="boulliau",short="Boulliau",name="Ismaël Boulliau",life="1605–1694",
  role="Astronomer and priest, born at Loudun; in Paris from 1632",side="sceptic; Grandier's admirer",where="Paris, relaying his brother's eyewitness report",
  lat=48.857,lon=2.352,vantage=3,vantage_label="Loudun native in Paris",form="dated letters",language="French",
  authenticity="His letter to Pierre Gassendi of 7 September 1634 survives in his correspondence and was printed in the 19th century by Tamizey de Larroque ('Document sur Urbain Grandier'). Cited here through a 2023 study in Comptes Rendus Mécanique.",
  bio="Boulliau had grown up in Loudun but left for Paris in 1632 and saw none of the exorcisms. Three weeks after the burning he sent Gassendi a short history of Grandier's death drawn from his brother Jean's eyewitness account, and condemned as impious the doctrine that a Christian could be put to death on the testimony of devils.",
  sources=[dict(title="Comptes Rendus Mécanique article on Boulliau (section on Loudun)",url=CRM)]),
 dict(id="surin",short="Surin",name="Jean-Joseph Surin SJ",life="1600–1665",
  role="Jesuit priest from Bordeaux, aged 34, sent to Loudun as exorcist with charge of the prioress",side="exorcists; Jesuit mystic",where="Loudun Dec 1634–Oct 1636 and 1637; Bordeaux; the 1638 journey",
  lat=47.010,lon=0.083,waypoints=[dict(lat=44.838,lon=-0.579,label="Bordeaux"),dict(lat=47.010,lon=0.083,label="Loudun, from Advent 1634"),dict(lat=44.838,lon=-0.579,label="Bordeaux, recalled 1636"),dict(lat=47.010,lon=0.083,label="Loudun again, 1637"),dict(lat=45.899,lon=6.129,label="Annecy, 1638")],
  vantage=0,vantage_label="the exorcist who said the demon passed into him",form="dated letters; memoir (written later)",language="French",
  authenticity="His letters of 1635–36 circulated in copies at the time. 'Triomphe de l'amour divin sur les puissances de l'Enfer' and 'Science expérimentale des choses de l'autre vie' were written c. 1658–60, more than twenty years after the events, after a long illness during which he could barely write; modern edition by Jacques Prunair (Grenoble: Millon, 1990), and an English translation, 'The Triumph of Divine Love over the Powers of Hell'.",
  bio="Surin arrived when the original exorcists had failed and chose patience, prayer and spiritual direction over public spectacle. He reported that the demon passed from the prioress into himself, and spent most of the next two decades in a condition he and his order took for possession or obsession. His late writings are both a theology of the case and a record of his own ordeal.",
  sources=[dict(title="The Triumph of Divine Love over the Powers of Hell (English translation, PDF)",url=TRI),dict(title="New Catholic Encyclopedia: Surin, Jean Joseph",url="https://encyclopedia.com/religion/encyclopedias-almanacs-transcripts-and-maps/surin-jean-joseph")]),
 dict(id="killigrew",short="Killigrew",name="Thomas Killigrew",life="1612–1683",
  role="English courtier, aged 23, travelling in France; later playwright and theatre manager",side="English visitor (Protestant)",where="Loudun, 1635, as a tourist of the exorcisms",
  lat=47.010,lon=0.083,vantage=1,vantage_label="visiting English courtier",form="letter",language="English",
  authenticity="His letter on the possessed nuns survives only in contemporary manuscript copies (Bodleian Ashmole 800; Pepys Library 2099; British Library Add. 27402; Cornell). J. Lough and D. E. L. Crane edited the text as 'a letter of 1635' (Durham University Journal, 1986). The exact day and recipient are not settled in the catalogues seen.",
  bio="Killigrew went to Loudun as many travellers did in 1635, when the exorcisms had become a destination for the curious from across Europe. His English letter, copied and passed around in England, is one of the few outsider accounts written at the time rather than recalled later.",
  sources=[dict(title="Cornell University Library: 'The copye of a letter written by Mr. Thomas Killigrew' [1635?]",url=COR)]),
 dict(id="lauderdale",short="Lauderdale",name="John Maitland, later Duke of Lauderdale",life="1616–1682",
  role="Young Scottish nobleman, aged about 21, on his travels in 1637; in 1659 a political prisoner",side="Scottish Presbyterian visitor; sceptic",where="Paris and Loudun, spring 1637; Windsor Castle, 1659",
  lat=47.010,lon=0.083,waypoints=[dict(lat=48.857,lon=2.352,label="Paris, spring 1637"),dict(lat=47.010,lon=0.083,label="Loudun, 1637"),dict(lat=51.483,lon=-0.604,label="Windsor Castle, letter 1659")],
  vantage=1,vantage_label="visitor who judged it a cheat",form="letter (written later)",language="English",
  authenticity="His letter to Richard Baxter, signed 'Lauderdaile' and dated at Windsor Castle, 12 March 1659, was printed by Baxter among the 'instances' in his book on spirits (1691) and reprinted as an appendix in Goldsmid's 1887 volumes. It recalls a visit made some 22 years earlier.",
  bio="Maitland went to Loudun from Paris in 1637, asked a Jesuit to show him the possessed, and watched an exorcism and the prioress's inscribed hand. He came away convinced of fraud. Writing two decades later to Baxter, who collected testimonies of the spirit world, he set Loudun apart as a pretended possession while offering other cases he thought genuine.",
  sources=[dict(title="Appendix to The History of the Devils of Loudun, tr. E. Goldsmid (1887), Project Gutenberg",url="https://gutenberg.org/cache/epub/45282/pg45282-images.html")]),
 dict(id="monconys",short="Monconys",name="Balthasar de Monconys",life="1611–1665",
  role="Lyon magistrate, traveller and amateur scientist",side="curious visitor",where="Loudun, 1645",
  lat=47.010,lon=0.083,vantage=1,vantage_label="travelling diarist",form="journal (travel diary, printed 1665–66)",language="French",
  authenticity="His 'Journal des voyages' was published posthumously in 1665–66. The Loudun visit is cited here through Michel de Certeau's 'The Possession at Loudun' (p. 221, as quoted in a secondary essay); the journal page itself has not been seen.",
  bio="Monconys kept a journal of his travels and experiments. At Loudun he was shown the prioress's hand and recorded that part of a letter came away under his fingernail, a small test that sceptics have cited ever since.",
  sources=[dict(title="Constellations essay drawing on de Certeau, The Possession at Loudun",url=CON)]),
 dict(id="tourette",short="Tourette",name="Georges Gilles de la Tourette (with Gabriel Legué)",life="1857–1904",
  role="Neurologist, pupil of J.-M. Charcot at the Salpêtrière",side="later investigators: the Salpêtrière school",where="Paris, 1886",
  lat=48.838,lon=2.364,vantage=4,vantage_label="19th-century medical editor",form="annotated edition",language="French",
  authenticity="Co-edited the first printing of Jeanne's autobiography (1886) with Gabriel Legué, in Bourneville's 'Bibliothèque diabolique', with a preface by Charcot. Jean Céard (1994) criticised the edition's notes for reading every symptom through the hysteria doctrine of the 1880s.",
  bio="The 1886 editors presented Jeanne's text as a case history and gave it a diagnostic subtitle. Their reading is itself a dated position, part of the Salpêtrière's project of 'retrospective medicine', and is reported here as such, not as a finding.",
  sources=[dict(title="J. Céard, 'Démonologie et démonopathies au temps de Charcot', Histoire des sciences médicales 28 (1994)",url=CEARD),dict(title="1886 edition (Internet Archive PDF)",url=JDA)]),
]

entries=[
 E("1630","1630",'year',"grandier","Poitiers / Loudun","Bishop's court condemns Grandier; he appeals",
   "Accused by Loudun enemies of misconduct, Grandier was condemned by the court of the bishop of Poitiers, Henri-Louis de La Rochepozay, to penance and barred from priestly functions in Loudun. He appealed, carrying the case beyond the diocese. The episode made the bishop and a faction of local notables his lasting adversaries.",
   "official record","approx","Goldsmid tr. of the 1634 'Véritable histoire' gives the sentence as 2 June 1630; other histories give early January 1630, so only the year is shown. "+GUT),
 E("1631-11-22","22 November 1631",'day',"sourdis","Bordeaux","Archbishop's tribunal acquits Grandier and restores him",
   "The archbishop of Bordeaux's tribunal acquitted Grandier on appeal and restored him to his functions in Loudun. For his enemies it was a defeat; for Grandier, a vindication that he made no effort to enjoy quietly.",
   "official record","verified","Date as given in Goldsmid's 1887 translation of the 1634 narrative. "+GUT),
 E("1632-09-22","night of 21–22 September 1632",'day',"jeanne","Ursuline convent, Loudun","A ghostly figure in the dormitory",
   "The first incident was a night apparition in the convent: the figure of the late confessor, Canon Moussaut, was reported by the nuns, and the prioress later wrote of nocturnal visitations and of something passing into her hand. The town had just come through a summer of plague. In her autobiography, written about ten years later, Jeanne tells this beginning as the opening of her trials.",
   "later firsthand","approx","Ecclesiastical records give 22 September (Stephenson, BPS 2014); de Certeau gives 21 September for the first sighting (Constellations essay). Autobiography written c. 1642–44. "+BPS),
 E("1632-10-05","5 October 1632",'day',"jeanne","Ursuline convent, Loudun","First exorcisms in the convent",
   "With three nuns now declared possessed, the convent's director Canon Jean Mignon and the priest Pierre Barré began exorcisms. The prioress fell into convulsions and answered in the demons' name. What had been a private disturbance of a poor convent was now a matter for the Church's rituals and soon for the town.",
   "official record","verified","1 October (three nuns declared possessed) and 5 October (first exorcisms) from ecclesiastical records as summarised by Stephenson (BPS 2014) and de Certeau. "+BPS),
 E("1632-10-11","11 October 1632",'day',"desniau","Loudun","The demons name Grandier; magistrates summoned",
   "After the evil spirit's declaration in the convent, Canon Mignon informed the civil magistrates. The name given was that of the curé of Saint-Pierre, Urbain Grandier. The believing chronicler records the step as the moment the case passed from the convent into the law.",
   "secondhand","verified","Goldsmid tr. of the 1634 'Véritable histoire'; date also in de Certeau (Constellations essay). "+GUT),
 E("1632-10","October 1632",'month',"grandier","Loudun","Grandier protests and asks for the nuns to be confined",
   "Grandier petitioned the authorities that his reputation was under attack and asked that the nuns be separated and examined. He took the accusation as one more move by his old enemies, Mignon among them.",
   "secondhand","approx","Reported in modern summaries of the affair; Grandier's petition text not seen."),
 E("1632-11-28","28 November 1632",'day',"desniau","Loudun","An envoy of the queen arrives to look into it",
   "The abbé Marescot came to Loudun to examine the matter on behalf of the queen. The chronicler notes the visit as a sign that the court was already watching the convent within two months of the first apparition.",
   "secondhand","verified","Goldsmid tr. of the 1634 narrative. "+GUT),
 E("1632-12","late 1632 – early 1633",'range',"sourdis","Bordeaux / Loudun","The archbishop halts the exorcisms",
   "After his physician's report, the archbishop of Bordeaux ordered the exorcisms stopped and the nuns kept apart. The manifestations faded, and for most of 1633 the affair seemed to be over.",
   "official record","approx","Reported in summaries of the affair; the ordinance's exact date not seen."),
 E("1633-09","September 1633",'month',"laubardemont","Loudun","Richelieu's man comes to pull down the keep",
   "Laubardemont arrived in Loudun to supervise the demolition of the castle keep, part of the Crown's dismantling of provincial fortresses. Some townsmen resisted. He heard about the convent and its accusations, and reported on Loudun's affairs to Paris.",
   "official record","approx","Month after standard histories; mission to demolish the tower reported in summaries of the affair."),
 E("1633-11-30","30 November 1633",'day',"laubardemont","Paris","Royal commission to investigate the possession",
   "A royal commission dated 30 November 1633 gave Laubardemont full powers to investigate the possession and Grandier's part in it, with orders for Grandier's arrest. The case was now the king's.",
   "official record","verified","Goldsmid tr. of the 1634 narrative gives the commission's date. "+GUT),
 E("1633-12-07","early December 1633",'range',"grandier","Loudun → Angers","Arrested and taken to Angers",
   "Grandier was arrested soon after Laubardemont's return and taken to the castle prison at Angers. His papers were seized; among them, by later report, was a manuscript treatise arguing that priests should be free to marry, first printed in 1866.",
   "official record","approx","Arrest date commonly given as 7 December 1633 (not verified here); treatise printed by R. Luzarche, Paris 1866 (Penn record)."),
 E("1633-12-17","17 December 1633",'day',"laubardemont","Loudun","The commissioner begins hearing witnesses",
   "Laubardemont opened his inquiry by hearing witnesses against Grandier, including old complaints unconnected with the convent. The exorcisms resumed under the commission's protection.",
   "official record","verified","Goldsmid tr. of the 1634 narrative. "+GUT),
 E("1634-05","May 1634",'month',"tranquille","Loudun","A written pact is produced in the church",
   "During the exorcisms the demon speaking through the prioress announced a pact, and a document was found, according to the exorcists' record, near the bishop of Poitiers' foot. It bore Grandier's name and the signatures of demons. Exorcists presented it as proof; Grandier's friends as forgery.",
   "official record","approx","Notre Dame research guide summary of the procès-verbaux. "+ND),
 E("1634-05-31","31 May 1634",'day',"laubardemont","Paris (Council of State)","Council decree shuts out all appeals",
   "A decree of the king's Council confirmed Laubardemont's powers, forbade the Parlement and other courts to intervene, and set a fine of 500 livres on any appeal. Grandier was brought back from Angers to Loudun.",
   "official record","verified","Goldsmid tr. (the text has a misprint in the day) and summaries of the affair. "+GUT),
 E("1634-06-23","23 June 1634",'day',"grandier","Church of Sainte-Croix, Loudun","Ordered to exorcise his accusers",
   "Grandier was brought into the church before the possessed nuns and ordered to act as exorcist. He could not refuse. The believing chronicler seized on his Latin formula, noting he said he was 'compelled' rather than that he 'commanded' the demons, as a telltale sign.",
   "secondhand","verified","Goldsmid tr. of the 1634 narrative records the 23 June session and the 'Cogor vos' detail. "+GUT),
 E("1634","1634",'year',"duncan","Saumur / Loudun","A physician argues for imagination, not demons",
   "Duncan, having seen the nuns, published anonymously a discourse arguing that their convulsions and speech were the work of a disordered imagination and melancholy rather than of devils. He did not accuse the nuns of deliberate fraud. Laubardemont took it badly, and Duncan was shielded by his patron Marshal de Brézé.",
   "firsthand","approx","Chalmers's Biographical Dictionary; Stephenson (BPS 2014). Exact month of publication not checked."),
 E("1634-07-08","8 July 1634",'day',"laubardemont","Loudun","The special court begins its sessions",
   "A court of judges drawn from neighbouring jurisdictions, presided over by Laubardemont, began the trial. Testimony from the exorcisms, including what the demons said, was admitted against the accused.",
   "official record","approx","Notre Dame research guide. "+ND),
 E("1634-08-18","18 August 1634",'day',"laubardemont","Loudun","Sentence: guilty of magic, to be burned",
   "The court declared Grandier guilty of magic and of causing the possession of the Ursulines, and sentenced him to be questioned under torture for accomplices and then burned, with his books and the pact, and his goods confiscated. The sentence was carried out the same day.",
   "official record","verified","Sentence of 18 August 1634, quoted in English in the Notre Dame guide; date in all sources. "+ND),
 E("1634-08-18","18 August 1634",'day',"grandier","Place Sainte-Croix, Loudun","Refuses to confess; burned the same day",
   "After torture Grandier still denied any pact or sorcery. He was taken to the square of Sainte-Croix before a large crowd and burned. Accounts agree he did not confess; they disagree about almost everything else that was said and done.",
   "secondhand","verified","Date in all sources; refusal to confess reported by friends and enemies alike."),
 E("1634-08-18","18 August 1634",'day',"desniau","Loudun","A believer watches him die impenitent",
   "The believing witness read Grandier's bearing at the end as hardness of heart: he records that the condemned man would not look at the crucifix held out to him, and treats his refusal to confess as the devil's last hold.",
   "secondhand","verified","Goldsmid tr. of the 1634 narrative (Grandier and the crucifix). "+GUT,quote="he never deigned to look at it"),
 E("1634-08-18","18 August 1634",'day',"tranquille","Loudun","The exorcists at the stake",
   "Tranquille and the Recollect Lactance were among the friars who attended Grandier to the place of execution and pressed him to confess. Lactance, by several accounts, lit the fire. The exorcists' printed relation presented the day as justice duly done.",
   "secondhand","approx","Notre Dame research guide (Lactance and the pyre)."),
 E("1634-09-07","7 September 1634",'day',"boulliau","Paris","A short history of the death, sent to Gassendi",
   "Three weeks after the burning, Boulliau wrote to Gassendi with an account of Grandier's death supplied by his brother Jean, who had been present. He condemned as impious and abominable the idea that Christians could be put to death on the testimony of devils.",
   "secondhand","verified","Letter of 7 September 1634, cited in Comptes Rendus Mécanique (Boulliau study), after Tamizey de Larroque. "+CRM),
 E("1634","autumn 1634",'range',"tranquille","Paris","A printed defence of the 'just procedures'",
   "The Véritable relation attributed to Tranquille set out the proceedings as lawful and the possession as real, answering the doubts circulating in Paris and the provinces. It was one of a flurry of pamphlets for and against.",
   "firsthand","approx","Title and 1634 date standard in bibliographies; month and attribution not verified here."),
 E("1634-12","Advent (December) 1634",'month',"surin","Loudun","A new exorcist arrives for the prioress",
   "The Jesuit Surin arrived in Advent 1634 to take charge of the prioress, who was still said to hold seven demons after Grandier's death. He resolved to work by spiritual direction and prayer more than by public confrontation. He wrote this down a quarter-century later.",
   "later firsthand","verified","Surin, Triumph of Divine Love (written c. 1658–60), ch. 1 and n. (December 1634); New Catholic Encyclopedia. "+TRI),
 E("1635-01-19","night of 19 January 1635",'day',"surin","Loudun","The exorcist feels himself assailed",
   "Surin dates to this night the first of the assaults he believed the demon made on him directly. From then on he described feeling another presence within himself during and after the exorcisms.",
   "later firsthand","verified","Surin, Triumph of Divine Love, with editor's footnote giving 19 January 1635. "+TRI),
 E("1635-02-02","2 February 1635",'day',"jeanne","Loudun","A turn on the feast of the Purification",
   "On the feast of the Purification, Surin reports, the prioress's weeping ceased and her disposition changed; he treated it as the start of her inner conversion. Her own autobiography tells the same years as a slow struggle against her vanity and the demons together.",
   "secondhand","verified","Surin, Triumph of Divine Love, n. 55. "+TRI),
 E("1635-05","spring 1635",'range',"surin","Loudun","Letters that travel: the exorcist possessed",
   "Surin described his own state in letters to fellow Jesuits that were copied and circulated; by July 1635 Mersenne and Peiresc were discussing him. He wrote that during his ministry the devil had passed from the possessed into him.",
   "firsthand","approx","Notre Dame guide (Mersenne–Peiresc letters, July 1635); JSTOR Daily summary. The specific letter usually cited is dated 3 May 1635 (not verified here)."),
 E("1635-09-08","8 September 1635",'day',"surin","Loudun","The prioress vows to become a lay sister",
   "On the feast of the Nativity of Our Lady the prioress made a vow, at Surin's urging, to become a lay sister if delivered, and Leviathan was said to withdraw for some days afterwards.",
   "later firsthand","verified","Surin, Triumph of Divine Love, n. 69. "+TRI),
 E("1635-11","late 1635",'range',"surin","Ursuline church, Loudun","'Joseph' appears on her hand",
   "At the departure of the demon Balaam, before visitors who included an English lord, the name JOSEPH was reported written on the prioress's left hand. An English pamphlet printed the procès-verbal as 'A relation of the devill Balams departure' (London, 1636).",
   "later firsthand","approx","Surin, Triumph (places it in autumn 1635); Goldsmid vol. appendix (Lord Montague, late 1635); 1636 English pamphlet (Wisconsin record). "+WIS),
 E("1635","1635",'year',"killigrew","Loudun","An English courtier writes home about the nuns",
   "Killigrew, aged 23, attended the exorcisms as a visitor and wrote an English letter describing what he saw of the possessed nuns. Copies of it passed from hand to hand in England and survive in at least four manuscript collections.",
   "firsthand","approx","Lough & Crane, Durham University Journal 1986 ('a letter of 1635'), via Cornell catalogue; content not read here. "+COR),
 E("1636-01-06","6 January 1636 (Epiphany)",'day',"surin","Loudun","Isacaaron departs; 'Maria' on the hand",
   "At the Epiphany exorcism, Surin wrote, the demon Isacaaron left the prioress and the name MARIA appeared in roman letters on her left hand. Formal attestations were drawn up on 8–9 January.",
   "later firsthand","verified","Surin, Triumph, with appendixes dated January 1636. "+TRI),
 E("1636-10","October 1636",'month',"surin","Loudun → Bordeaux","Recalled, unable to go on",
   "Surin's condition worsened until he could no longer write, and his superiors withdrew him from Loudun. He later said this incapacity, beginning in October 1636, lasted with intervals for some twenty years.",
   "later firsthand","verified","Surin, Triumph, n. 75; New Catholic Encyclopedia. "+TRI),
 E("1637","spring 1637",'range',"lauderdale","Loudun","A Scots visitor asks to see the possessed",
   "Being in Paris in the spring, Maitland rode to Loudun, told a Jesuit he had come a long way, and was shown an exorcism and the prioress's hand. He concluded that the nuns' performance was a cheat and that the letters on the hand had been made with acid. He wrote this down 22 years later.",
   "later firsthand","verified","Lauderdale to Baxter, Windsor Castle, 12 March 1659, in Goldsmid 1887 appendix.",quote="it was apparent to me it was done with aquafortis"),
 E("1637","early 1637",'range',"jeanne","Loudun","Near death, and healed by Saint Joseph",
   "Gravely ill with fever and pleurisy and given the last rites, the prioress reported a vision of Saint Joseph, who anointed her; she recovered at once, and an oil said to come from the unction was preserved on her shift. Her autobiography gives this as a turning point; Surin records the healing too.",
   "later firsthand","approx","Surin, Triumph (illness, extreme unction, healing; no exact date); de Certeau dates the recovery spring 1637 (Constellations essay)."),
 E("1637-10-15","15 October 1637 (feast of St Teresa)",'day',"surin","Loudun","Behemoth leaves; 'Jesus' completes the hand",
   "Back in Loudun, Surin led a retreat that ended on the feast of Saint Teresa. At Communion, he wrote, the last demon, Behemoth, departed, and the names of Jesus and of Francis de Sales were added to Joseph and Maria on her hand. The two had vowed in September to visit Francis de Sales's tomb at Annecy.",
   "later firsthand","verified","Surin, Triumph (vow 17 September 1637; Behemoth 15 October 1637). "+TRI),
 E("1638-04","late April 1638",'range',"surin","Bordeaux → Savoy","Setting out for Annecy",
   "After Easter, Surin left Bordeaux for Annecy, still largely unable to speak, to meet the prioress at the tomb of Francis de Sales. At Annecy he stayed nine days near Jeanne de Chantal; he wrote that his speech partly returned on the road home.",
   "later firsthand","verified","Surin, Triumph, ch. on the journey (Easter 12 April 1638). "+TRI),
 E("1638-05","spring–summer 1638",'range',"jeanne","Rueil, Saint-Germain, Paris, Annecy","Showing the hand to cardinal, king and queen",
   "On her journey the prioress was received by Richelieu at Rueil and by the king and the pregnant queen, and showed the names on her hand to crowds she counted in thousands a day. She tells the tour in her autobiography as both triumph and temptation to pride.",
   "later firsthand","approx","Autobiography (1886 ed.); Surin, Triumph (queen pregnant; Louis XIV born 5 Sept 1638); Stephenson (BPS 2014). Order and exact days not verified."),
 E("1638","1638",'year',"jeanne","Loudun","Asking the queen for help for a poor house",
   "After the tour the prioress wrote to the queen describing the convent's poverty and asking for material support, and later sent an itemised request to the royal treasury. Fame had not paid the community's bills.",
   "firsthand","approx","De Certeau, The Possession at Loudun, p. 205, as cited in the Constellations essay. "+CON),
 E("1638","1638",'year',"tranquille","Loudun","Death of an exorcist",
   "Tranquille died in 1638 after a long affliction that believers attributed to the demons he had fought; one account has the demons crying that he was dead. Lactance had died within weeks of the burning, and the surgeon Mannoury soon after; friends of the exorcists read the deaths as the devils' revenge, Grandier's friends otherwise.",
   "secondhand","approx","Goldsmid 1887 volumes (later narrative portion); year commonly given as 1638. "+GUT),
 E("1644","c. 1642–1644",'range',"jeanne","Loudun","Writing her life for her director",
   "At the request of her Jesuit director Saint-Jure, the prioress wrote her autobiography, about ten years after the possession began. It is a confession as much as a memoir: she accuses herself of vanity and of having sometimes not known where the demons ended and she began, while affirming the possession and her deliverance.",
   "later firsthand","approx","Dates of composition as given by the 1886 and 1990 editors; Stephenson (BPS) gives 1644."),
 E("1645","1645",'year',"monconys","Loudun","A traveller's fingernail and the sacred names",
   "Visiting Loudun, the diarist Monconys was shown the prioress's hand and recorded that part of a letter came away when he worked at it with his fingernail. The names IOSEPH and MARIA were still there, renewed, Surin says, about every fortnight and on great feasts.",
   "firsthand","approx","De Certeau p. 221 via Constellations essay; Surin, Triumph (renewals). Journal page not seen. "+CON),
 E("1659-03","12 March 1659 (English dating)",'month',"lauderdale","Windsor Castle","From prison, a sceptic's testimony for Baxter",
   "Writing to Richard Baxter, who was gathering evidence for the reality of spirits, Maitland called Loudun a pretended possession and a cheat, while offering other cases he believed genuine. He asked that his stories not be printed; Baxter printed them in 1691.",
   "later firsthand","verified","Letter signed 'Lauderdaile', Goldsmid 1887 appendix. "+"https://gutenberg.org/cache/epub/45282/pg45282-images.html",quote="I do not doubt to call a pretended possession"),
 E("1660-08","early August 1660",'month',"surin","Bordeaux","Able to write again: the Triumph",
   "After years in which he could not write, Surin resumed and set down his history of the Loudun exorcisms as 'The Triumph of Divine Love', a theology of the case and a memoir of his own darkness. By 1663 he noted that the names on the prioress's hand had faded away.",
   "later firsthand","verified","Surin, Triumph (resumed writing August 1660; last renewal 24 June 1662; names gone by 1663). "+TRI),
 E("1886","1886",'year',"tourette","Paris","Physicians publish the prioress as a case of hysteria",
   "Legué and Gilles de la Tourette printed Jeanne's autobiography for the first time, in Bourneville's 'Bibliothèque diabolique', with a preface by Charcot presenting her as a classic example of hysteria unchanged across the ages. Their notes read each episode as a symptom. A century later the historian Jean Céard criticised the edition for stripping the account of its time.",
   "secondhand","verified","BnF record of the reissue; Céard 1994. "+CEARD),
]

convergences=[
 dict(date="1632-10-11",label="The demons name Grandier",eyes=["jeanne","desniau","grandier"],note="The prioress's later memoir, the believing chronicler's dated narrative and Grandier's protest give three readings of one accusation: a torment suffered, a crime uncovered, a plot by old enemies."),
 dict(date="1633-12",label="The king's commission and Grandier's arrest",eyes=["laubardemont","grandier","desniau"],note="The commission of 30 November and the hearings from 17 December appear as plain dates in the state's papers and in the chronicle; for Grandier they were the end of the protection that had saved him in 1631."),
 dict(date="1634-06-23",label="The accused made exorcist",eyes=["grandier","desniau","tranquille"],note="The same session is a trap and a test: believers watched for a slip in the Latin, and found one; his friends saw a man forced to play a part in his own prosecution."),
 dict(date="1634-08-18",label="Sentence and burning",eyes=["laubardemont","grandier","desniau","tranquille","boulliau"],note="The commissioner's sentence, the believer's account of an impenitent death, the exorcists' presence at the stake and Boulliau's letter three weeks later on his brother's testimony: four ways of telling one day, from justice done to judicial killing."),
 dict(date="1635-01",label="The exorcist and the prioress",eyes=["surin","jeanne"],note="Surin's later Triumph and Jeanne's later autobiography describe the same months from two sides of the grille, each claiming the other's struggle as part of their own."),
 dict(date="1635-11",label="Names on the hand, and visitors from England",eyes=["surin","killigrew","jeanne"],note="Late 1635 brought the first name on the prioress's hand and a stream of foreign visitors; the exorcist recorded a sign, the English courtier a spectacle worth a letter home."),
 dict(date="1637",label="Healing, last demon, and a sceptic's visit",eyes=["jeanne","surin","lauderdale"],note="In the same year the prioress reported her healing by Saint Joseph and Surin the departure of the last demon, while a young Scot who saw the hand concluded it had been written with acid."),
 dict(date="1638-05",label="The prioress on tour",eyes=["jeanne","surin"],note="Her account of crowds and court and his of a silent journey to Annecy describe the same pilgrimage, one as public vindication, the other as private recovery."),
 dict(date="1645",label="The hand under scrutiny",eyes=["monconys","lauderdale","tourette"],note="A traveller's fingernail in 1645, a prisoner's recollection in 1659 and physicians' notes in 1886 each examined the marks with the tools of their time, and reached conclusions that are themselves dated."),
]

